-- MTA-STS policy state for customer-owned domains.
-- The policy itself is generated by the API at
-- https://mta-sts.<domain>/.well-known/mta-sts.txt from these columns.
BEGIN;

ALTER TABLE mail_domains
  ADD COLUMN IF NOT EXISTS mta_sts_mode text NOT NULL DEFAULT 'none',
  ADD COLUMN IF NOT EXISTS mta_sts_max_age integer NOT NULL DEFAULT 604800,
  ADD COLUMN IF NOT EXISTS mta_sts_verified boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS mta_sts_last_error text NOT NULL DEFAULT '';

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'mail_domains_mta_sts_mode_check'
  ) THEN
    ALTER TABLE mail_domains
      ADD CONSTRAINT mail_domains_mta_sts_mode_check
      CHECK (mta_sts_mode IN ('none', 'testing', 'enforce'));
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'mail_domains_mta_sts_max_age_check'
  ) THEN
    ALTER TABLE mail_domains
      ADD CONSTRAINT mail_domains_mta_sts_max_age_check
      CHECK (mta_sts_max_age BETWEEN 86400 AND 31557600);
  END IF;
END $$;

INSERT INTO schema_migrations (version) VALUES ('0008_mta_sts')
ON CONFLICT (version) DO NOTHING;

COMMIT;
